const text = $input.first().json.text;
const docId = $input.first().json.document_id;
const filename = $input.first().json.filename;

const chunkSize = 500;
const words = text.split(' ');
const chunks = [];
let current = [];
let currentLen = 0;
let chunkNum = 1;

for (const word of words) {
  current.push(word);
  currentLen += word.length + 1;

  if (currentLen >= chunkSize) {
    chunks.push({
      document_id: docId,
      filename: filename,
      chunk_number: chunkNum,
      text: current.join(' '),
    });
    current = [];
    currentLen = 0;
    chunkNum++;
  }
}

if (current.length > 0) {
  chunks.push({
    document_id: docId,
    filename: filename,
    chunk_number: chunkNum,
    text: current.join(' '),
  });
}

return chunks;
